updated AS (
  UPDATE public.logistica_attrezzature t
  SET
    assegnatario = s.assegnatario,
    famiglia_attrezzi = s.famiglia_attrezzi,
    marca = s.marca,
    descrizione_articolo = s.descrizione_articolo,
    serial_number = s.serial_number,
    modello = s.modello,
    oda = s.oda,
    data_oda = s.data_oda,
    posizione = s.posizione,
    ddt = s.ddt,
    stato_valore = s.stato_valore,
    note = s.note,
    active = true,
    updated_at = now()
  FROM src s
  WHERE lower(coalesce(t.codice_cronos, '')) = lower(coalesce(s.codice_cronos, ''))
)
INSERT INTO public.logistica_attrezzature(
  codice_cronos,
  assegnatario,
  famiglia_attrezzi,
  marca,
  descrizione_articolo,
  serial_number,
  modello,
  oda,
  data_oda,
  posizione,
  ddt,
  stato_valore,
  note,
  active
)
SELECT
  s.codice_cronos,
  s.assegnatario,
  s.famiglia_attrezzi,
  s.marca,
  s.descrizione_articolo,
  s.serial_number,
  s.modello,
  s.oda,
  s.data_oda,
  s.posizione,
  s.ddt,
  s.stato_valore,
  s.note,
  true
FROM src s
WHERE NOT EXISTS (
  SELECT 1
  FROM public.logistica_attrezzature t
  WHERE lower(coalesce(t.codice_cronos, '')) = lower(coalesce(s.codice_cronos, ''))
);
